// Remote exec helper for the LIVE Soul Pilates box (.200).
// Decrypts server.rootPasswordEnc in-memory (never prints it), SSHes in,
// ASSERTS hostname -I contains 51.79.226.200, then runs the given command.
//
// Usage: node remote.mjs '<remote bash command>'
//   command is read from argv[2], or from stdin if argv[2] === '-'
import { Client } from "ssh2";
import { createDecipheriv, scryptSync } from "node:crypto";
import { readFileSync } from "node:fs";
import pg from "pg";

const SERVER_ID = "cmsc9l72y000ghl7iyd87u5ja";
const EXPECT_IP = "51.79.226.200";

function loadEnv(path) {
  const env = {};
  for (const line of readFileSync(path, "utf8").split("\n")) {
    const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)$/);
    if (!m) continue;
    let v = m[2].trim();
    if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) v = v.slice(1, -1);
    env[m[1]] = v;
  }
  return env;
}

function deriveKey(secret) {
  return scryptSync(secret, "nxeon-byok", 32);
}
function decryptSecret(enc, secret) {
  if (!enc) return null;
  const [ivB64, tagB64, dataB64] = enc.split(":");
  const decipher = createDecipheriv("aes-256-gcm", deriveKey(secret), Buffer.from(ivB64, "base64"));
  decipher.setAuthTag(Buffer.from(tagB64, "base64"));
  const dec = Buffer.concat([decipher.update(Buffer.from(dataB64, "base64")), decipher.final()]);
  return dec.toString("utf8");
}

async function main() {
  let cmd = process.argv[2];
  if (cmd === "-") cmd = readFileSync(0, "utf8");
  if (!cmd) { console.error("no command given"); process.exit(2); }

  const env = loadEnv("/opt/nxeon/.env");
  const client = new pg.Client({ connectionString: env.DATABASE_URL });
  await client.connect();
  const { rows } = await client.query(
    'SELECT "rootPassword","rootPasswordEnc","sshPort","ipAddress" FROM "Server" WHERE id=$1',
    [SERVER_ID]
  );
  await client.end();
  if (!rows.length) { console.error("server row not found"); process.exit(3); }
  const srv = rows[0];
  const password = decryptSecret(srv.rootPasswordEnc, env.AUTH_SECRET) ?? srv.rootPassword;
  if (!password) { console.error("no password"); process.exit(4); }
  const host = srv.ipAddress || EXPECT_IP;
  const port = 22;

  // Wrap the command with a hard hostname assertion.
  const guarded =
    `if ! hostname -I | grep -q ${EXPECT_IP}; then echo "HOST ASSERT FAILED"; exit 99; fi\n` + cmd;

  const conn = new Client();
  conn
    .on("ready", () => {
      conn.exec(guarded, (err, stream) => {
        if (err) { console.error(err); process.exit(5); }
        stream
          .on("close", (code) => { conn.end(); process.exit(code || 0); })
          .on("data", (d) => process.stdout.write(d))
          .stderr.on("data", (d) => process.stderr.write(d));
      });
    })
    .on("error", (e) => { console.error("SSH error:", e.message); process.exit(6); })
    .connect({ host, port, username: "root", password, readyTimeout: 20000 });
}
main().catch((e) => { console.error(e); process.exit(1); });

// Remote exec helper for the LIVE Soul Pilates box (.200).
// Decrypts server.rootPasswordEnc in-memory (never prints it), SSHes in,
// ASSERTS hostname -I contains 51.79.226.200, then runs the given command.
//
// Usage: node remote.mjs '<remote bash command>'
//   command is read from argv[2], or from stdin if argv[2] === '-'
import { Client } from "ssh2";
import { createDecipheriv, scryptSync } from "node:crypto";
import { readFileSync } from "node:fs";
import pg from "pg";

const SERVER_ID = "cmsc9l72y000ghl7iyd87u5ja";
const EXPECT_IP = "51.79.226.200";

function loadEnv(path) {
  const env = {};
  for (const line of readFileSync(path, "utf8").split("\n")) {
    const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)$/);
    if (!m) continue;
    let v = m[2].trim();
