using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;
using SoulPilates.Core.Entities;
using System;
using System.Collections.Generic;

namespace SoulPilates.Core.Entities;

public class CalendarSession : BaseEntity
{
    [BsonRepresentation(BsonType.ObjectId)]
    public string? ClassBlueprintId { get; set; }

    [BsonRepresentation(BsonType.ObjectId)]
    public string? InstructorId { get; set; }

    public DateTime StartTime { get; set; }
    public DateTime EndTime { get; set; }

    public int Capacity { get; set; }
    public int CurrentBookings { get; set; }

    public string Status { get; set; } = "SCHEDULED"; // "SCHEDULED", "CANCELLED", "COMPLETED", "NO_SHOW", "BLOCKED"

    // SPM-91 — Public visibility. When false, the session is hidden from the
    // public booking page and cannot be reserved through the public reserve
    // path; admin/instructor read + internal booking are unaffected.
    // Defaults to TRUE so existing MongoDB documents (missing the field)
    // deserialize as PUBLIC.
    public bool IsPublic { get; set; } = true;

    // Denormalized from ClassBlueprint at creation time for fast public API reads
    public string ClassName { get; set; } = "";
    public string FocusArea { get; set; } = "FULL_BODY";
    public string DifficultyLevel { get; set; } = "ALL_LEVELS"; // "BEGINNER", "INTERMEDIATE", "ADVANCED", "ALL_LEVELS"
    public string Format { get; set; } = "GROUP"; // "GROUP", "MAT", "PRIVATE", "DUO"

    // Denormalized from Staff at creation time
    public string InstructorName { get; set; } = "";

    // ── Customer Booking Portal — Denormalized for fast public reads ──
    public string? EquipmentType { get; set; }                   // From ClassBlueprint (legacy singular = first of EquipmentTypes)

    /// <summary>
    /// SPM-71 — Denormalized list of equipment type names from the ClassBlueprint.
    /// The legacy singular <see cref="EquipmentType"/> is kept populated from the
    /// FIRST entry for backward compatibility. Defaults to an empty list so existing
    /// MongoDB documents (which only have the singular field) deserialize safely —
    /// callers treat a missing/empty list as <c>[EquipmentType]</c>.
    /// </summary>
    public List<string> EquipmentTypes { get; set; } = new();    // From ClassBlueprint

    public string? ImageUrl { get; set; }                        // From ClassBlueprint
    public List<string> Tags { get; set; } = new();              // From ClassBlueprint
    public string? InstructorPhotoUrl { get; set; }              // From Staff

    // Blocked time slot reason (null = normal class, set = blocked/unavailable)
    public string? BlockedReason { get; set; }

    // ── V2.1: Block Scope — scoped blocks per format/difficulty ──

    /// <summary>
    /// Block scope: "GLOBAL" (blocks all classes), "FORMAT" (blocks a specific format),
    /// "DIFFICULTY" (blocks a specific difficulty level).
    /// Null for non-block sessions.
    /// </summary>
    public string? BlockScope { get; set; }

    /// <summary>
    /// The scoped value when BlockScope is "FORMAT" or "DIFFICULTY".
    /// e.g., "GROUP", "BEGINNER". Null when BlockScope is "GLOBAL" or for non-blocks.
    /// </summary>
    public string? BlockScopeValue { get; set; }

    // P4-S01 — Back-pointer to the RecurringScheduleRule that auto-created
    // Legacy V1 FK — kept for backward compat with existing MongoDB docs.
    // V2 sessions use Origin / ClassBlueprintId instead. Do not reference
    // this field in new code.
    [Obsolete("V2: Use Origin + ClassBlueprintId instead. This field is retained only for existing MongoDB documents.")]
    [BsonRepresentation(BsonType.ObjectId)]
    public string? RecurringScheduleRuleId { get; set; }

    // P5-PWA — Idempotency tag flipped by ClassReminderJob once we've
    // pushed the 15-minute pre-class notification to the instructor.
    // Stored on the session (not on Attendance) because the alert
    // recipient is per-session, not per-booking.
    public bool InstructorReminderSent { get; set; }

    // ── V2: Session Origin ──
    // Tracks how this session came into existence. The calendar renderer
    // uses this to apply different styling (blocks get stripes, freelance
    // gets dashed borders, overrides get a badge, etc.).

    /// <summary>
    /// How this session was created:
    /// <list type="bullet">
    /// <item><c>MATERIALISED</c> — auto-generated from a blueprint's WeeklySlots</item>
    /// <item><c>MANUAL</c> — admin/instructor hand-created (makeup, ad-hoc)</item>
    /// <item><c>OVERRIDE</c> — replaced a materialised session for one date</item>
    /// <item><c>FREELANCE</c> — manually scheduled freelance rental session</item>
    /// <item><c>BLOCK</c> — admin-created block (not a real class)</item>
    /// </list>
    /// </summary>
    public string Origin { get; set; } = "MATERIALISED";

    // ── V2: Override Tracking ──

    /// <summary>True if this session is a one-off override of a blueprint-materialised occurrence.</summary>
    public bool IsOverride { get; set; } = false;

    /// <summary>Admin/instructor note explaining why the session was overridden.</summary>
    public string? OverrideNote { get; set; }

    // ── V2: Freelance Tracking ──

    /// <summary>True if this is a freelance rental session (uses freelance credit math).</summary>
    public bool IsFreelance { get; set; } = false;

    /// <summary>The freelancer (Staff) renting the studio for this session.</summary>
    [BsonRepresentation(BsonType.ObjectId)]
    public string? FreelanceStaffId { get; set; }

    /// <summary>If the freelancer is paying from a pre-paid credit package, this is the package ID.</summary>
    public string? FreelancePackageId { get; set; }

    /// <summary>Actual headcount at session completion (for group freelance credit math: 1 credit per student).</summary>
    public int? FreelanceHeadcount { get; set; }

    /// <summary>Freelance session format: "GROUP" (headcount-based credits) or "PRIVATE" (flat 1 credit).</summary>
    public string? FreelanceFormat { get; set; }

    /// <summary>
    /// Explicit freelance billing mode chosen at scheduling time.
    /// Null on legacy sessions, where the system falls back to package presence.
    /// </summary>
    public string? FreelanceBillingMode { get; set; }

    /// <summary>Linked invoice for single-class freelance rentals that are paid at checkout.</summary>
    [BsonRepresentation(BsonType.ObjectId)]
    public string? FreelanceInvoiceId { get; set; }

    /// <summary>Total amount charged for a single-class freelance rental.</summary>
    public decimal? FreelanceChargeAmount { get; set; }

    // ── V2: Snapshot of blueprint drop-in price at materialisation time ──

    /// <summary>
    /// Drop-in price snapshot from the blueprint at the time this session was
    /// materialised/created. Ensures historical pricing integrity even if the
    /// blueprint price changes later.
    /// </summary>
    public decimal? DropInPrice { get; set; }
}

