        HeadcountTiersSnapshot = (rates?.HeadcountTiers ?? staff.HeadcountTiers).Select(h => new HeadcountPayoutTier
        {
            MinStudents = h.MinStudents,
            MaxStudents = h.MaxStudents,
            RatePerStudent = h.RatePerStudent,
        }).ToList(),
        PrivateHeadcountTiersSnapshot = (rates?.PrivateHeadcountTiers ?? staff.PrivateHeadcountTiers).Select(h => new HeadcountPayoutTier
        {
            MinStudents = h.MinStudents,
            MaxStudents = h.MaxStudents,
            RatePerStudent = h.RatePerStudent,
        }).ToList(),

        BaseSalaryAmount = rates?.BaseSalary ?? staff.BaseSalary,
    };

    // ── Aggregate session-level earnings ───────────────────────────
    // Private fractional revenue is summed *raw* here, then the commission
    // rate is applied below once we know the class count for tier resolution.
    //
    // For PERCENTAGE_TIERED group classes, we also accumulate raw group revenue
    // so the tiered commission can be applied at the end.
    decimal privateRawRevenue = 0;
    decimal groupRawRevenue = 0;
    int totalClassesWithAttendees = 0;
    // Historical spreadsheet imports carry the exact per-class commission on
    // each attendance (ImportedCommissionAmount) — the studio's real rates were
    // manually negotiated per month, so they can't be recomputed. We total
    // these verbatim and fold them in AFTER the tier logic (which would
    // otherwise overwrite PrivateClassEarnings for PERCENTAGE_TIERED).
    decimal importedGroupComm = 0;
    decimal importedPrivateComm = 0;
    foreach (var session in sessions)
    {
        // Load attendances that actually showed up (CHECKED_IN or ARRIVED)
        // — the frontend sets "ARRIVED" via the status dropdown, but some
        // legacy code paths set "CHECKED_IN" directly. Accept both.
        var rawArrivedAttendances = await _attendances
            .Find(a => a.CalendarSessionId == session.Id
                    && (a.Status == "CHECKED_IN" || a.Status == "ARRIVED")
                    && a.Status != "CANCELLED")
            .ToListAsync();

        // SPM-113 — money: an arrival only counts toward the instructor's
        // commission if the attendee both arrived AND paid. The owner
        // decision is to apply the paid rule EVERYWHERE — earnings total,
        // head-count payout, and tier thresholds — so we filter the arrived
        // set here, BEFORE it feeds any of those calculations. Genuinely
        // unpaid monetary arrivals count nowhere; PACKAGE_CREDIT and free
        // classes remain satisfied (see IsAttendancePaidAsync). The filter
        // is a pure read, so re-runs stay idempotent.
        var arrivedAttendances = new List<Attendance>();
        foreach (var a in rawArrivedAttendances)
        {
            if (await IsAttendancePaidAsync(a)) arrivedAttendances.Add(a);
        }

        // Only count towards tiers if at least one paid attendee arrived.
        // Empty classes (or classes with only unpaid arrivals) must not
        // inflate the tier counter or generate any payout.
        if (arrivedAttendances.Count == 0) continue;

        var isPrivateFmt = session.Capacity == 1 || session.Format == "PRIVATE" || session.Format == "DUO";

        // ── Imported historical commission short-circuit ──
        // If any attendee in this session carries a spreadsheet-imported
        // commission, use those amounts verbatim and skip the recompute for
        // this whole session (imported sessions are all-or-nothing).
        // Sum every imported commission on the session — the spreadsheet's
        // amount is authoritative even for rows flagged "doesn't count as a
        // class" (they still carried a recorded commission in the P&L).
        var importedForSession = arrivedAttendances
            .Where(a => a.ImportedCommissionAmount.HasValue)
            .Sum(a => a.ImportedCommissionAmount!.Value);
        if (arrivedAttendances.Any(a => a.ImportedCommissionAmount.HasValue))
        {
            totalClassesWithAttendees++;
            if (isPrivateFmt) { result.TotalPrivateClasses++; importedPrivateComm += importedForSession; }
            else { result.TotalGroupClasses++; importedGroupComm += importedForSession; }
            continue;
        }

        var isPrivate = session.Capacity == 1 || session.Format == "PRIVATE";
        if (!isPrivate)
        {
            result.TotalGroupClasses++;
            totalClassesWithAttendees++;

            if (result.CommissionModelSnapshot == "FIXED_HEADCOUNT")
            {
                // SPM-90 — the headcount ladder is per SEAT, not per attendance
                // ROW. A group booking of N seats (att.Quantity == N) counts as
                // N students, exactly like PERCENTAGE_TIERED sums per-attendee
                // revenue with quantity. Empty-arrival attendees
                // (CountsTowardsCommission == false) are excluded from the count.
                var seatHeadcount = arrivedAttendances
                    .Where(a => a.CountsTowardsCommission)
                    .Sum(a => Math.Max(1, a.Quantity));

                result.GroupClassEarnings += ResolveHeadcountPayoutFromSnapshot(result, seatHeadcount);
            }
            else if (result.CommissionModelSnapshot == "PERCENTAGE_TIERED")
            {
                // ── PERCENTAGE_TIERED for group classes ──────────────────
                // The instructor earns a % of the revenue generated by the
                // attendees who arrived. Revenue per attendee is determined
                // from their linked invoice paid balance, falling back to
                // the session's drop-in price.
                foreach (var att in arrivedAttendances)
                {
                    if (!att.CountsTowardsCommission) continue;

                    var revenueBase = await ResolveAttendeeRevenueAsync(att, session);

                    // Apply referral discount.
                    var discountPct = att.ReferralDiscountPct.HasValue
                        ? Math.Clamp(att.ReferralDiscountPct.Value, 0m, 1m)
                        : 0m;
                    var seatRev = revenueBase * (1m - discountPct);
                    // Net any booking-page promo discount (e.g. bring-a-friend free seat).
                    if (att.PromoDiscountAmount is > 0m)
                        seatRev = Math.Max(0m, seatRev - att.PromoDiscountAmount.Value);
                    groupRawRevenue += seatRev;
                }

                // Also add flat rate + per-head if configured (hybrid model).
                result.GroupClassEarnings += result.GroupFlatRatePerClassSnapshot;
                result.GroupClassEarnings += result.GroupRatePerHeadSnapshot * arrivedAttendances.Count;
            }
            else
            {
                // Default flat-rate model.
                result.GroupClassEarnings += result.GroupFlatRatePerClassSnapshot;
                result.GroupClassEarnings += result.GroupRatePerHeadSnapshot * arrivedAttendances.Count;
            }
        }
        else
        {
            result.TotalPrivateClasses++;
            totalClassesWithAttendees++;

            if (result.CommissionModelSnapshot == "FIXED_HEADCOUNT")
            {
                var seatHeadcount = arrivedAttendances
                    .Where(a => a.CountsTowardsCommission)
                    .Sum(a => Math.Max(1, a.Quantity));

                result.PrivateClassEarnings += ResolveHeadcountPayoutFromSnapshot(result, seatHeadcount, isPrivate: true);
            }
            else
            {
                foreach (var att in arrivedAttendances)
                {
                    if (!att.CountsTowardsCommission) continue;

                    var revenueBase = await ResolveAttendeeRevenueAsync(att, session);

                    // Apply referral discount.
                    var discountPct = att.ReferralDiscountPct.HasValue
                        ? Math.Clamp(att.ReferralDiscountPct.Value, 0m, 1m)
                        : 0m;
                    var seatRev = revenueBase * (1m - discountPct);
                    if (att.PromoDiscountAmount is > 0m)
                        seatRev = Math.Max(0m, seatRev - att.PromoDiscountAmount.Value);
                    privateRawRevenue += seatRev;
                }
            }
        }
    }

    // ── Apply tiered commission rates ──────────────────────────────
    // For PERCENTAGE_TIERED, the tier is resolved using the TOTAL class
    // count (group + private) that had at least one arrived attendee.
    // The same rate applies to both group and private raw revenue.
    if (result.CommissionModelSnapshot == "PERCENTAGE_TIERED")
    {
        var totalCountForTier = totalClassesWithAttendees;
        var tieredRate = ResolvePrivateCommissionRateFromSnapshot(result, totalCountForTier);
        result.PrivateClassEarnings = privateRawRevenue * tieredRate;
        result.GroupClassEarnings += groupRawRevenue * tieredRate;
    }
    else if (result.CommissionModelSnapshot != "FIXED_HEADCOUNT")
    {
        // Non-tiered flat model: apply the flat private commission rate to the
        // raw revenue accumulated in the loop.
        //
        // FIXED_HEADCOUNT MUST be excluded here. Its private earnings are already
        // final — computed per-session from the headcount tiers inside the loop
        // (see ResolveHeadcountPayoutFromSnapshot above). This branch would
        // otherwise overwrite that with `privateRawRevenue * privateRate`, and
        // privateRawRevenue is only ever accumulated on the percentage path, so
        // for a headcount instructor it is 0 — zeroing out every private-class
        // commission (the Linna bug).
        var privateRate = ResolvePrivateCommissionRateFromSnapshot(result, result.TotalPrivateClasses);
        result.PrivateClassEarnings = privateRawRevenue * privateRate;
    }

    // Fold in the verbatim spreadsheet-imported commissions AFTER the tier
    // logic (which overwrites PrivateClassEarnings for PERCENTAGE_TIERED).
    result.GroupClassEarnings += importedGroupComm;
    result.PrivateClassEarnings += importedPrivateComm;

    result.TotalPay = result.BaseSalaryAmount + result.GroupClassEarnings + result.PrivateClassEarnings;
    return result;
}

/// <inheritdoc />
public async Task<decimal> CalculateTotalCommissionsAsync(DateTime start, DateTime end)
{
    // Mirror CalculatePayrollAsync's session scope, but don't persist a run.
    var sessions = await _sessions
        .Find(s => s.StartTime >= start && s.StartTime <= end
                && s.Status == "COMPLETED"
                && s.Origin != "BLOCK")
        .ToListAsync();

    decimal total = 0m;
    foreach (var group in sessions.GroupBy(s => s.InstructorId))
    {
        var instructorId = group.Key;
        if (string.IsNullOrEmpty(instructorId)) continue;

        var staff = await _staff.Find(s => s.Id == instructorId).FirstOrDefaultAsync();
        if (staff is null) continue;

        var revision = await _revisions.ResolveAsOfAsync(staff.Id!, end);
        revision = await ApplyCommissionOverrideAsync(staff.Id!, end, revision);

        var result = await AggregateInstructorAsync(staff, revision, group.ToList());
        total += result.GroupClassEarnings + result.PrivateClassEarnings;
    }
    return total;
}

